// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).

use kayak_rt::*;
use super::*;

// lower.kfx: an FX-26 program, checked, lowered to the engine's IR (C58).
// Names are resolved: a local to its frame's depth and slot, a global to
// its index, a primitive to its value. Types are dropped (`the`, a
// binder's type, `plambda`, `proj`), and FX-26's derived forms (`let*`,
// `cond`, `and`, `or`, `when`) made of the core.

// Where names are: the frames' names, the innermost first; the globals, in
// the order they are defined, an index each.
pub type Scope = List<Strings>;

pub fn position_of(mut n: Str, mut xs: Strings, mut i: i64) -> i64 {
    loop {
        if null_p(xs) {
            return -1i64;
        } else if string_eq_p(car(xs), n) {
            return i;
        } else {
            (xs, i) = (cdr(xs), i64_plus(i, 1i64));
            continue;
        }
    }
}

/// A local's depth and slot, or nothing.
pub fn find_local(mut n: Str, mut sc: Scope, mut depth: i64) -> List<i64> {
    loop {
        if null_p(sc) {
            return nil::<i64>();
        } else {
            let i = position_of(n, car(sc), 0i64);
            if i64_gt_eq(i, 0i64) {
                return kayak_rt::heap_cons(depth, kayak_rt::heap_cons(i, kayak_rt::nil()));
            } else {
                (sc, depth) = (cdr(sc), i64_plus(depth, 1i64));
                continue;
            }
        }
    }
}

pub fn binder_name(p: &'static Sexp) -> Str {
    let tagcase_ = p;
    match *tagcase_ {
        Sexp::Sym(n, f, x) => {
            n
        }
        Sexp::Lst(xs, f, l, x) => {
            sym_name(car(xs))
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

/// A body's forms, its docstring dropped.
pub fn without_doc(body: Sexps) -> Sexps {
    if (not(null_p(cdr(body))) && {
        let tagcase_ = car(body);
        match *tagcase_ {
            Sexp::Str(s, f, p) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        cdr(body)
    } else {
        body
    }
}

pub fn digits_int(mut cs: List<char>, mut n: Int) -> Int {
    loop {
        if null_p(cs) {
            return n;
        } else {
            (cs, n) = (cdr(cs), _plus(_star(n, int_lit(10)), i64_to_int(i64_minus(char_to_i64(car(cs)), 48i64))));
            continue;
        }
    }
}

/// A literal past an `i64`.
pub fn big_int(text: Str) -> Int {
    let cs = string_chars(text);
    if char_eq_p(car(cs), '-') {
        _minus(int_lit(0), digits_int(cdr(cs), int_lit(0)))
    } else {
        digits_int(cs, int_lit(0))
    }
}

// The globals a program defines, in order: each definition's name, and a
// datatype's constructors.
pub fn global_names(forms: Sexps) -> Strings {
    if null_p(forms) {
        nil::<Str>()
    } else {
        let f = car(forms);
        onto(if (head_is_p(f, str_lit("define")) || head_is_p(f, str_lit("define*"))) {
            kayak_rt::heap_cons(binder_name(second(items(f))), kayak_rt::nil())
        } else if head_is_p(f, str_lit("define-rec")) {
            map(lambda1(move |g: &'static Sexp| {
                sym_name(car(items(g)))
            }), cdr(items(f)))
        } else if head_is_p(f, str_lit("define-datatype")) {
            map(lambda1(move |g: &'static Sexp| {
                sym_name(car(items(g)))
            }), cdr(cdr(items(f))))
        } else {
            nil::<Str>()
        }, global_names(cdr(forms)))
    }
}

pub fn lower(e: &'static Sexp, sc: Scope, gs: Strings) -> &'static Ir {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Num(k, f, p) => {
            i_lit(v_int(i64_to_int(k)))
        }
        Sexp::Big(text, f, p) => {
            i_lit(v_int(big_int(text)))
        }
        Sexp::Chr(c, f, p) => {
            i_lit(v_char(c))
        }
        Sexp::Str(s, f, p) => {
            i_lit(v_string(s))
        }
        Sexp::Real(x, f, p) => {
            error(str_lit("the engine: no reals yet"))
        }
        Sexp::Sym(n, f, p) => {
            lower_name(n, sc, gs)
        }
        Sexp::Lst(xs, f, l, p) => {
            if null_p(xs) {
                i_lit(v_nil())
            } else {
                let h = {
                    let tagcase_ = car(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, f2, p2) => {
                            n
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("")
                        }
                    }
                };
                if (not(string_eq_p(h, str_lit(""))) && null_p(find_local(h, sc, 0i64))) {
                    lower_form(h, cdr(xs), e, sc, gs)
                } else {
                    i_call(lower(car(xs), sc, gs), lower_all(cdr(xs), sc, gs))
                }
            }
        }
        _ => {
            let other = tagcase_;
            error(str_lit("the engine: a datum it cannot lower"))
        }
    }
}

pub fn lower_all(es: Sexps, sc: Scope, gs: Strings) -> Irs {
    if null_p(es) {
        nil::<&'static Ir>()
    } else {
        kayak_rt::heap_cons(lower(car(es), sc, gs), lower_all(cdr(es), sc, gs))
    }
}

pub fn lower_body(body: Sexps, sc: Scope, gs: Strings) -> &'static Ir {
    let forms = without_doc(body);
    if null_p(cdr(forms)) {
        lower(car(forms), sc, gs)
    } else {
        i_seq(lower_all(forms, sc, gs))
    }
}

pub fn lower_name(n: Str, sc: Scope, gs: Strings) -> &'static Ir {
    let local = find_local(n, sc, 0i64);
    if not(null_p(local)) {
        i_local(car(local), car(cdr(local)))
    } else if string_eq_p(n, str_lit("#t")) {
        i_lit(v_bool(true))
    } else if string_eq_p(n, str_lit("#f")) {
        i_lit(v_bool(false))
    } else if string_eq_p(n, str_lit("#u")) {
        i_lit(v_unit())
    } else if i64_gt_eq(position_of(n, gs, 0i64), 0i64) {
        i_global(position_of(n, gs, 0i64), n)
    } else if string_eq_p(n, str_lit("nil")) {
        i_lit(v_nil())
    } else if i64_gt_eq(prim_arity(n), 0i64) {
        i_lit(v_prim(n, prim_arity(n)))
    } else {
        error(string_append(str_lit("the engine: nothing is named "), n));
        i_lit(v_unit())
    }
}

pub fn lower_form(h: Str, xs: Sexps, e: &'static Sexp, sc: Scope, gs: Strings) -> &'static Ir {
    if string_eq_p(h, str_lit("the")) {
        lower(second(xs), sc, gs)
    } else if string_eq_p(h, str_lit("quote")) {
        i_lit(v_symbol(string_to_symbol(sym_name(car(xs)))))
    } else if (string_eq_p(h, str_lit("plambda")) || string_eq_p(h, str_lit("proj"))) {
        if string_eq_p(h, str_lit("proj")) {
            lower(car(xs), sc, gs)
        } else {
            lower(second(xs), sc, gs)
        }
    } else if string_eq_p(h, str_lit("lambda")) {
        let names = map(&binder_name, items(car(xs)));
        i_lambda(size(names), lower_body(cdr(xs), kayak_rt::heap_cons(names, sc), gs))
    } else if string_eq_p(h, str_lit("if")) {
        i_if(lower(car(xs), sc, gs), lower(second(xs), sc, gs), lower(third(xs), sc, gs))
    } else if string_eq_p(h, str_lit("begin")) {
        i_seq(lower_all(xs, sc, gs))
    } else if string_eq_p(h, str_lit("let")) {
        let bs = items(car(xs));
        i_let(map(lambda1(move |b: &'static Sexp| {
            lower(last(items(b)), sc, gs)
        }), bs), lower_body(cdr(xs), kayak_rt::heap_cons(map(lambda1(move |b: &'static Sexp| {
            binder_name(car(items(b)))
        }), bs), sc), gs))
    } else if string_eq_p(h, str_lit("let*")) {
        let bs = items(car(xs));
        if null_p(bs) {
            lower_body(cdr(xs), sc, gs)
        } else {
            i_let(kayak_rt::heap_cons(lower(last(items(car(bs))), sc, gs), kayak_rt::nil()), lower_form(str_lit("let*"), kayak_rt::heap_cons(lst(cdr(bs), str_lit(""), 0i64, 0i64), cdr(xs)), e, kayak_rt::heap_cons(kayak_rt::heap_cons(binder_name(car(items(car(bs)))), kayak_rt::nil()), sc), gs))
        }
    } else if string_eq_p(h, str_lit("letrec")) {
        let bs = items(car(xs));
        let inner = kayak_rt::heap_cons(map(lambda1(move |b: &'static Sexp| {
            binder_name(car(items(b)))
        }), bs), sc);
        i_letrec(map(lambda1(move |b: &'static Sexp| {
            lower(last(items(b)), inner, gs)
        }), bs), lower_body(cdr(xs), inner, gs))
    } else if string_eq_p(h, str_lit("cond")) {
        lower_cond(xs, sc, gs)
    } else if string_eq_p(h, str_lit("and")) {
        if null_p(xs) {
            i_lit(v_bool(true))
        } else if null_p(cdr(xs)) {
            lower(car(xs), sc, gs)
        } else {
            i_if(lower(car(xs), sc, gs), lower_form(str_lit("and"), cdr(xs), e, sc, gs), i_lit(v_bool(false)))
        }
    } else if string_eq_p(h, str_lit("or")) {
        if null_p(xs) {
            i_lit(v_bool(false))
        } else if null_p(cdr(xs)) {
            lower(car(xs), sc, gs)
        } else {
            i_if(lower(car(xs), sc, gs), i_lit(v_bool(true)), lower_form(str_lit("or"), cdr(xs), e, sc, gs))
        }
    } else if string_eq_p(h, str_lit("list")) {
        if null_p(xs) {
            i_lit(v_nil())
        } else {
            i_call(i_lit(v_prim(str_lit("cons"), 2i64)), kayak_rt::heap_cons(lower(car(xs), sc, gs), kayak_rt::heap_cons(lower_form(str_lit("list"), cdr(xs), e, sc, gs), kayak_rt::nil())))
        }
    } else if string_eq_p(h, str_lit("sum")) {
        i_sum(sym_name(car(xs)), lower(second(xs), sc, gs))
    } else if string_eq_p(h, str_lit("product")) {
        i_product(map(lambda1(move |f: &'static Sexp| {
            sym_name(car(items(f)))
        }), xs), map(lambda1(move |f: &'static Sexp| {
            lower(second(items(f)), sc, gs)
        }), xs))
    } else if string_eq_p(h, str_lit("extract")) {
        i_extract(sym_name(second(xs)), lower(car(xs), sc, gs))
    } else if string_eq_p(h, str_lit("tagcase")) {
        lower_tagcase(xs, sc, gs)
    } else if string_eq_p(h, str_lit("prompt")) {
        i_prompt(lower(car(xs), sc, gs), lower(third(xs), sc, gs), lower(second(xs), sc, gs))
    } else {
        i_call(lower_name(h, sc, gs), lower_all(xs, sc, gs))
    }
}

pub fn lower_cond(clauses: Sexps, sc: Scope, gs: Strings) -> &'static Ir {
    if null_p(clauses) {
        i_lit(v_unit())
    } else {
        let c = items(car(clauses));
        if sym_is_p(car(c), str_lit("else")) {
            lower_body(cdr(c), sc, gs)
        } else {
            i_if(lower(car(c), sc, gs), lower_body(cdr(c), sc, gs), lower_cond(cdr(clauses), sc, gs))
        }
    }
}

/// `(tagcase e (tag x body) (tag (x ...) body) ... (else x body))`.
pub fn lower_tagcase(xs: Sexps, sc: Scope, gs: Strings) -> &'static Ir {
    let arms = cdr(xs);
    let default = concat(map(lambda1(move |a: &'static Sexp| {
        if sym_is_p(car(items(a)), str_lit("else")) {
            the::<Sexps>(kayak_rt::heap_cons(a, kayak_rt::nil()))
        } else {
            nil::<&'static Sexp>()
        }
    }), arms));
    let named = concat(map(lambda1(move |a: &'static Sexp| {
        if sym_is_p(car(items(a)), str_lit("else")) {
            nil::<&'static Sexp>()
        } else {
            the::<Sexps>(kayak_rt::heap_cons(a, kayak_rt::nil()))
        }
    }), arms));
    i_tagcase(lower(car(xs), sc, gs), map(lambda1(move |a: &'static Sexp| {
        let parts = items(a);
        let binder = second(parts);
        let names = {
            let tagcase_ = binder;
            match *tagcase_ {
                Sexp::Lst(ys, f, l, p) => {
                    map(&binder_name, ys)
                }
                _ => {
                    let other = tagcase_;
                    the::<Strings>(kayak_rt::heap_cons(binder_name(binder), kayak_rt::nil()))
                }
            }
        };
        arm(sym_name(car(parts)), size(names), lower_body(cdr(cdr(parts)), kayak_rt::heap_cons(names, sc), gs))
    }), named), if null_p(default) {
        i_lit(v_unit())
    } else {
        let parts = items(car(default));
        lower_body(cdr(cdr(parts)), kayak_rt::heap_cons(kayak_rt::heap_cons(binder_name(second(parts)), kayak_rt::nil()), sc), gs)
    })
}

// A top-level form: a definition, its global's value; an expression, its
// own (a string too, which `fixpt eval` writes); the rest (types,
// effects) nothing.
pub enum Top {
    TopDefine(&'static Ir),
    TopExpr(&'static Ir),
    TopNone(),
}

pub fn top_define(f0: &'static Ir) -> &'static Top {
    kayak_rt::heap_alloc(Top::TopDefine(f0))
}

pub fn top_expr(f0: &'static Ir) -> &'static Top {
    kayak_rt::heap_alloc(Top::TopExpr(f0))
}

pub fn top_none() -> &'static Top {
    kayak_rt::heap_alloc(Top::TopNone())
}

pub fn lower_tops(forms: Sexps, gs: Strings) -> List<&'static Top> {
    if null_p(forms) {
        nil::<&'static Top>()
    } else {
        let f = car(forms);
        onto(if {
            let tagcase_ = f;
            match *tagcase_ {
                Sexp::Str(s, fl, p) => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        } {
            kayak_rt::heap_cons(top_expr(i_lit(v_string({
                let tagcase_ = f;
                match *tagcase_ {
                    Sexp::Str(s, fl, p) => {
                        s
                    }
                    _ => {
                        let other = tagcase_;
                        str_lit("")
                    }
                }
            }))), kayak_rt::nil())
        } else if head_is_p(f, str_lit("define")) {
            let xs = items(f);
            kayak_rt::heap_cons(top_define(i_define(position_of(binder_name(second(xs)), gs, 0i64), lower(last(xs), nil::<List<Str>>(), gs))), kayak_rt::nil())
        } else if head_is_p(f, str_lit("define*")) {
            let xs = items(f);
            kayak_rt::heap_cons(top_define(i_define(position_of(binder_name(second(xs)), gs, 0i64), lower(last(xs), nil::<List<Str>>(), gs))), kayak_rt::nil())
        } else if head_is_p(f, str_lit("define-rec")) {
            map(lambda1(move |g: &'static Sexp| {
                let ys = items(g);
                top_define(i_define(position_of(sym_name(car(ys)), gs, 0i64), lower(last(ys), nil::<List<Str>>(), gs)))
            }), cdr(items(f)))
        } else if head_is_p(f, str_lit("define-datatype")) {
            map(lambda1(move |g: &'static Sexp| {
                let ys = items(g);
                top_define(i_define(position_of(sym_name(car(ys)), gs, 0i64), i_lit(v_ctor(sym_name(car(ys)), i64_minus(size(ys), 1i64)))))
            }), cdr(cdr(items(f))))
        } else if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-effect")) || head_is_p(f, str_lit("define-generative"))) {
            kayak_rt::heap_cons(top_none(), kayak_rt::nil())
        } else {
            kayak_rt::heap_cons(top_expr(lower(f, nil::<List<Str>>(), gs)), kayak_rt::nil())
        }, lower_tops(cdr(forms), gs))
    }
}

